-- Orientation is no longer part of the MEGS pipeline. Contract signing is a paper contract
-- generated by the system, wet-signed, and uploaded as a scan that only TA/Admin can read.

-- 1. Rename the stage in place so existing rows keep their position in the pipeline.
ALTER TYPE "ApplicationStatus" RENAME VALUE 'CONTRACT_AND_ORIENTATION' TO 'CONTRACT_SIGNING';

-- 2. Signed contract scans are stored as their own document category.
ALTER TYPE "DocumentCategory" ADD VALUE IF NOT EXISTS 'CONTRACT';

-- 3. The signed contract is no longer an applicant-uploaded compliance requirement.
--    Only empty requirements are relaxed so already-approved documents stay on record.
UPDATE "ComplianceRequirement"
SET "isRequired" = false
WHERE "documentId" IS NULL
  AND (LOWER("documentLabel") LIKE '%signed employment contract%'
       OR LOWER("documentLabel") LIKE '%signed contract%');

-- 4. Drop orientation and the pasted contract link; add the fields the contract template needs.
ALTER TABLE "Application"
  DROP COLUMN "orientationCompleted",
  DROP COLUMN "orientationCompletedAt",
  DROP COLUMN "orientationDate",
  DROP COLUMN "orientationNotes",
  DROP COLUMN "contractDocumentUrl",
  ADD COLUMN "contractStartDate" TIMESTAMP(3),
  ADD COLUMN "contractPosition" TEXT,
  ADD COLUMN "contractDailyRate" DECIMAL(10, 2),
  ADD COLUMN "contractSignedById" TEXT,
  ADD COLUMN "contractDocumentId" INTEGER;
